/**
 * API ortam yapılandırması.
 * Projenizin ortamlarına göre baseUrl değerlerini düzenleyin.
 */

const ApiEnvironment = {
  Type: {
    local: "local",
    test: "test",
    localTest: "localTest",
    release: "release",
  } as const,

  // TODO: Projenizin API URL'lerini buraya ekleyin
  baseUrls: {
    local: "https://localhost:7001/api",
    test: "https://test.example.com/api",
    localTest: "http://10.34.60.1:5000/api",
    release: "https://api.example.com/api",
  } as Record<string, string>,
};

export type EnvironmentType =
  (typeof ApiEnvironment.Type)[keyof typeof ApiEnvironment.Type];

export default ApiEnvironment;

/**
 * LocalStorage key sabitleri.
 * Tüm localStorage erişimleri bu sabitler üzerinden yapılmalıdır.
 * Key değiştirmek isterseniz sadece burayı güncellemeniz yeterlidir.
 */
const StorageKeys = {
  ACCESS_TOKEN: "access_token",
  USER: "user",
} as const;

export default StorageKeys;

import ApiEnvironment from "@/constants/ApiEnvironment";

const Environment = {
  getEnvironment: () => {
    if (typeof window === "undefined") {
      return process.env.NODE_ENV === "development"
        ? ApiEnvironment.Type.local
        : ApiEnvironment.Type.release;
    }

    const { host } = window.location;

    if (host.includes("localhost") || host.includes("127.0.0.1")) {
      return ApiEnvironment.Type.local;
    }
    if (host.includes("test")) {
      return ApiEnvironment.Type.test;
    }
    if (host.includes("ngrok")) {
      return ApiEnvironment.Type.local;
    }
    if (host.includes("10.34.60.")) {
      return ApiEnvironment.Type.localTest;
    }
    return ApiEnvironment.Type.release;
  },

  getBaseUrl: () => {
    const env = Environment.getEnvironment();
    return ApiEnvironment.baseUrls[env] ?? "/api";
  },

  isLocal: () => Environment.getEnvironment() === ApiEnvironment.Type.local,
  isRelease: () => Environment.getEnvironment() === ApiEnvironment.Type.release,
};

export default Environment;

/* eslint-disable @typescript-eslint/no-explicit-any */
import axios from "axios";
import type { AxiosResponse } from "axios";
import Environment from "@/utilities/Environment";

// ─── Custom Response Type ────────────────────────────────────────────────────
export interface CustomAxiosResponse<T = any> extends AxiosResponse<T> {
  data: T;
  error?: boolean;
  message?: string | null;
}

// ─── Logout Ref (interceptor'dan AuthContext.logout tetiklemek için) ─────────
let logoutCallback: (() => void) | null = null;

export function setAxiosLogoutCallback(callback: () => void) {
  logoutCallback = callback;
}

// ─── Axios Instance ──────────────────────────────────────────────────────────
const RequestService = axios.create({
  baseURL: Environment.getBaseUrl(),
  timeout: 30_000,
});

RequestService.defaults.headers.head["Content-Type"] = "application/json";
RequestService.defaults.validateStatus = (status) => status < 500;

// ─── Auth Token Management ───────────────────────────────────────────────────
export function setAxiosAuthToken(token: string | null) {
  if (token) {
    RequestService.defaults.headers.common.Authorization = `Bearer ${token}`;
  } else {
    delete RequestService.defaults.headers.common.Authorization;
  }
}

// ─── Response Interceptor ────────────────────────────────────────────────────
RequestService.interceptors.response.use(
  (response) => {
    // 401 Unauthorized → otomatik logout
    if (response.status === 401 && logoutCallback) {
      logoutCallback();
    }

    return {
      ...response,
      message: (response.data as any)?.message ?? null,
      error: (response.data as any)?.error ?? false,
      data:
        (response.data as any)?.data ??
        (response.data as any)?.Result ??
        response.data,
    };
  },
  (error) => {
    // Network error veya 5xx durumlarında da 401 kontrolü
    if (error?.response?.status === 401 && logoutCallback) {
      logoutCallback();
    }
    console.error("[Axios Error]", error);
    return Promise.reject(error);
  },
);

// ─── Request Interceptor ─────────────────────────────────────────────────────
RequestService.interceptors.request.use(
  (request) => request,
  (error) => Promise.reject(error),
);

export default RequestService;

/* eslint-disable @typescript-eslint/no-explicit-any */
import {
  createContext,
  createRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import RequestService, {
  setAxiosAuthToken,
  setAxiosLogoutCallback,
  type CustomAxiosResponse,
} from "@/lib/axios-config";
import StorageKeys from "@/constants/StorageKeys";

// ─── Types ───────────────────────────────────────────────────────────────────
export interface AuthUser {
  [key: string]: any;
}

export interface AuthContextValue {
  isAuthenticated: boolean;
  isLoading: boolean;
  user: AuthUser | null;
  authToken: string | null;
  login: (data: Record<string, any>) => Promise<void>;
  logout: () => Promise<void>;
  getUserDetail: () => Promise<void>;
}

// ─── Auth Logout Ref (for interceptors) ──────────────────────────────────────
export const authLogoutRef = createRef<{ logout: () => Promise<void> }>();

// ─── Context ─────────────────────────────────────────────────────────────────
const AuthContext = createContext<AuthContextValue | null>(null);

// ─── Helper: Response Check ──────────────────────────────────────────────────
function isResponseSuccessful(response: CustomAxiosResponse<any>): boolean {
  return (
    response &&
    response.status >= 200 &&
    response.status < 300 &&
    !response.error
  );
}

// ─── Provider ────────────────────────────────────────────────────────────────
export function AuthProvider({ children }: { children: ReactNode }) {
  const [authToken, setAuthToken] = useState<string | null>(() =>
    localStorage.getItem(StorageKeys.ACCESS_TOKEN),
  );
  const [isAuthenticated, setIsAuthenticated] = useState(
    !!localStorage.getItem(StorageKeys.ACCESS_TOKEN),
  );
  const [isLoading, setIsLoading] = useState(true);
  const [user, setUser] = useState<AuthUser | null>(null);

  const clearUserInfo = () => {
    localStorage.removeItem(StorageKeys.ACCESS_TOKEN);
    localStorage.removeItem(StorageKeys.USER);
    setAuthToken(null);
    setIsAuthenticated(false);
    setAxiosAuthToken(null);
  };

  const logout = async () => {
    if (!isAuthenticated) return;
    clearUserInfo();
    setUser(null);
  };

  const login = async (data: Record<string, any>) => {
    // TODO: Login endpoint'inize göre düzenleyin
    const response: CustomAxiosResponse<any> = await RequestService.post(
      "/auth/login",
      data,
    );
    if (isResponseSuccessful(response)) {
      const token = response.data?.token ?? response.data?.accessToken;
      setAuthToken(token);
      localStorage.setItem(StorageKeys.ACCESS_TOKEN, token);
      setAxiosAuthToken(token);
      setIsAuthenticated(true);
      setUser(response.data);
    } else {
      setUser(null);
      throw new Error(response.message ?? "Giriş başarısız");
    }
  };

  const getUserDetail = async () => {
    // TODO: User detail endpoint'inize göre düzenleyin
    const response = await RequestService.get("/auth/me");
    if (isResponseSuccessful(response)) {
      setUser(response.data);
    }
  };

  useImperativeHandle(authLogoutRef, () => ({ logout }));

  // Axios interceptor'a logout callback'i kaydet
  useEffect(() => {
    setAxiosLogoutCallback(() => {
      clearUserInfo();
      setUser(null);
    });
  }, []);

  // Token doğrulama
  useEffect(() => {
    const verifyToken = async () => {
      setIsLoading(true);
      if (!authToken) {
        clearUserInfo();
        setIsLoading(false);
        return;
      }
      setAxiosAuthToken(authToken);
      try {
        // TODO: Token doğrulama endpoint'inize göre düzenleyin
        const response = await RequestService.get("/auth/me");
        if (isResponseSuccessful(response)) {
          setIsAuthenticated(true);
          setUser(response.data);
        } else {
          clearUserInfo();
        }
      } catch {
        clearUserInfo();
      }
      setIsLoading(false);
    };

    verifyToken();
  }, [authToken]);

  const value = useMemo(
    () => ({
      isAuthenticated,
      isLoading,
      user,
      authToken,
      login,
      logout,
      getUserDetail,
    }),
    [isAuthenticated, isLoading, user, authToken],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

// ─── Hook ────────────────────────────────────────────────────────────────────
export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within an AuthProvider");
  return context;
}

export {
  useAuth,
  AuthProvider,
  authLogoutRef,
} from "@/contexts/auth/AuthContext";
export type { AuthUser, AuthContextValue } from "@/contexts/auth/AuthContext";

/* eslint-disable @typescript-eslint/no-explicit-any */
import RequestService from "@/lib/axios-config";
import type { CustomAxiosResponse } from "@/lib/axios-config";
import type { AxiosRequestConfig } from "axios";

/**
 * Servis oluşturma kalıbı.
 * Her controller için bir servis objesi tanımlayın.
 *
 * @example
 * // services/UserService.ts
 * import { createService } from '@/services/BaseService';
 *
 * const UserService = createService('User/', {
 *   login: (data) => UserService.post('Login', data),
 *   detail: () => UserService.get(''),
 *   list: () => UserService.get('List'),
 *   create: (data) => UserService.post('Create', data),
 *   update: (data) => UserService.patch('Update', data),
 * });
 *
 * export default UserService;
 */

interface ServiceMethods {
  get: <T = any>(
    endpoint: string,
    config?: AxiosRequestConfig,
  ) => Promise<CustomAxiosResponse<T>>;
  post: <T = any>(
    endpoint: string,
    data?: any,
    config?: AxiosRequestConfig,
  ) => Promise<CustomAxiosResponse<T>>;
  put: <T = any>(
    endpoint: string,
    data?: any,
    config?: AxiosRequestConfig,
  ) => Promise<CustomAxiosResponse<T>>;
  patch: <T = any>(
    endpoint: string,
    data?: any,
    config?: AxiosRequestConfig,
  ) => Promise<CustomAxiosResponse<T>>;
  delete: <T = any>(
    endpoint: string,
    config?: AxiosRequestConfig,
  ) => Promise<CustomAxiosResponse<T>>;
}

/**
 * Controller bazlı servis oluşturur.
 * İkinci parametre ile özel servis metodlarını tanımlayabilirsiniz.
 */
export function createService<
  T extends Record<string, (...args: any[]) => any>,
>(
  controller: string,
  methods: (service: ServiceMethods) => T,
): T & ServiceMethods {
  const baseMethods: ServiceMethods = {
    get: (endpoint, config) =>
      RequestService.get(
        `${controller}${endpoint}`,
        config,
      ) as Promise<CustomAxiosResponse>,
    post: (endpoint, data, config) =>
      RequestService.post(
        `${controller}${endpoint}`,
        data,
        config,
      ) as Promise<CustomAxiosResponse>,
    put: (endpoint, data, config) =>
      RequestService.put(
        `${controller}${endpoint}`,
        data,
        config,
      ) as Promise<CustomAxiosResponse>,
    patch: (endpoint, data, config) =>
      RequestService.patch(
        `${controller}${endpoint}`,
        data,
        config,
      ) as Promise<CustomAxiosResponse>,
    delete: (endpoint, config) =>
      RequestService.delete(
        `${controller}${endpoint}`,
        config,
      ) as Promise<CustomAxiosResponse>,
  };

  const customMethods = methods(baseMethods);

  return { ...baseMethods, ...customMethods };
}

/**
 * Response başarılı mı kontrolü.
 */
export function isResponseSuccessful(
  response: CustomAxiosResponse<any>,
): boolean {
  return (
    response &&
    response.status >= 200 &&
    response.status < 300 &&
    !response.error
  );
}

export default RequestService;
